```typescript
export function parseQueryString(qs: string): Record<string, string | string[]> {
  if (!qs || qs === '?') return {};
  const raw = qs.startsWith('?') ? qs.slice(1) : qs;
  return raw.split('&').reduce<Record<string, string | string[]>>((acc, pair) => {
    const [key, val = ''] = pair.split('=').map(decodeURIComponent);
    if (!key) return acc;
    const existing = acc[key];
    if (existing === undefined) {
      acc[key] = val;
    } else if (Array.isArray(existing)) {
      existing.push(val);
    } else {
      acc[key] = [existing, val];
    }
    return acc;
  }, {});
}
